package com.bhashasetu.service;
import com.bhashasetu.dto.EligibilityDtos.*; import java.util.*; import org.springframework.stereotype.Service;
@Service public class ConversationService {
 private final RedisSessionService sessions; private final ProfileExtractionService extractor; private final NormalizationService normalizer; private final EligibilityService eligibility;
 private static final Map<String,String> QUESTIONS=Map.of("state_or_ut","आप किस राज्य या केंद्र शासित प्रदेश में रहते हैं?","age","आपकी उम्र कितनी है?","occupation","क्या आप विद्यार्थी, किसान, नौकरीपेशा, स्वरोज़गार या बेरोज़गार हैं?","family_annual_income","अगर पता हो, आपके परिवार की सालाना आय कितनी है?");
 public ConversationService(RedisSessionService s,ProfileExtractionService e,NormalizationService n,EligibilityService l){sessions=s;extractor=e;normalizer=n;eligibility=l;}
 public Map<String,Object> turn(ConversationRequest request){if(request.text()==null||request.text().isBlank())throw new IllegalArgumentException("text is required");String id=request.sessionId()==null||request.sessionId().isBlank()?"default":request.sessionId();RedisSessionService.State state=sessions.get(id); Set<String> skipped=new HashSet<>(request.skippedFields()==null?List.of():request.skippedFields()); if(request.skip()){sessions.touch(id);}else{Map<String,Object> update=normalizer.normalizeAttributes(extractor.extract(request.text(),state.profile(),request.answerField()));state=sessions.merge(id,update);} List<EligibilityResult> results=eligibility.evaluateAll(state.profile()); List<String> schemes=results.stream().filter(r->r.status().equals("ELIGIBLE")).map(EligibilityResult::schemeName).toList();List<String> potential=results.stream().filter(r->r.status().equals("POTENTIALLY_ELIGIBLE")).map(EligibilityResult::schemeName).toList(); EligibilityResult pending=results.stream().filter(r->r.status().equals("NEED_MORE_INFORMATION")&&!r.missingFields().isEmpty()).findFirst().orElse(null); Map<String,Object> q=null;String text;if(pending!=null){String field=pending.missingFields().stream().filter(QUESTIONS::containsKey).filter(f->!skipped.contains(f)).findFirst().orElse(null);if(field!=null){q=Map.of("field",field,"text",QUESTIONS.get(field),"optional",true,"sensitive",false,"scheme_names",List.of());text=QUESTIONS.get(field);}else text="कुछ योजनाओं के लिए अभी और जानकारी चाहिए। नीचे बाकी आवश्यक जानकारी देखें।";}else if(!schemes.isEmpty())text="दी गई जानकारी के आधार पर कुछ योजनाओं के लिए आप पात्र दिखाई देते हैं। नीचे योजनाएँ और कारण देखें।";else if(!potential.isEmpty())text="आपकी जानकारी के आधार पर कुछ योजनाएँ संभावित रूप से मेल खाती हैं। अंतिम पात्रता के लिए बाकी शर्तों की पुष्टि करें।";else text="दी गई जानकारी से अभी कोई योजना मेल नहीं खाती। नीचे कारण देखें; आप अपनी जानकारी बदल भी सकते हैं।"; if(pending==null){sessions.finalize(id,state);state=new RedisSessionService.State(state.profile(),state.attempts(),true);} Map<String,Object> out=new LinkedHashMap<>();out.put("user_text",request.text());out.put("ai_text",text);out.put("schemes",schemes);out.put("potential_schemes",potential);out.put("eligibility_results",results);out.put("missing_fields",q==null?List.of():List.of(q.get("field")));out.put("next_question",q);out.put("result_cards",List.of());out.put("skipped_fields",skipped.stream().sorted().toList());out.put("session",Map.of("profile",state.profile(),"attempts",state.attempts(),"finalized",state.finalized()));out.put("audio_url",null);return out; }
}
